$ErrorActionPreference='Stop';$Here=Split-Path -Parent $MyInvocation.MyCommand.Path;$Repo=Split-Path -Parent $Here;$arch=$env:PROCESSOR_ARCHITECTURE;$bin=if($arch -eq 'ARM64'){'zorin-host-agent-windows-arm64.exe'}else{'zorin-host-agent-windows-amd64.exe'};$Exe=Join-Path $Repo (Join-Path 'dist' $bin);$AdbCmd=Get-Command adb.exe -ErrorAction SilentlyContinue;if($null-eq$AdbCmd){$AdbCmd=Get-Command adb -ErrorAction SilentlyContinue};if($null-ne$AdbCmd){$AdbPath=$AdbCmd.Source;if(-not$AdbPath){$AdbPath=$AdbCmd.Path};& $Exe daemon --adb $AdbPath}else{& $Exe daemon}
